"""Server-rendered admin dashboard HTML, generated from the original
standalone admin/index.html so the file is never a publicly reachable
static asset — it only gets served via api/admin-page.py after login.
"""

DASHBOARD_HTML_TEMPLATE = '<!doctype html>\n<html lang="vi">\n<head>\n<meta charset="utf-8" />\n<meta name="viewport" content="width=device-width, initial-scale=1" />\n<title>MediaPipe API — Admin</title>\n<style>\n  :root { color-scheme: dark; }\n  * { box-sizing: border-box; }\n  body { margin:0; font-family: -apple-system, Segoe UI, Roboto, sans-serif; background:#0b0f14; color:#e6edf3; }\n  header { padding:16px 24px; border-bottom:1px solid #1f2937; display:flex; align-items:center; gap:16px; }\n  header h1 { font-size:16px; margin:0; font-weight:600; }\n  nav { display:flex; gap:4px; padding:12px 24px 0; }\n  nav button { background:none; border:none; color:#8b949e; padding:10px 16px; cursor:pointer; border-bottom:2px solid transparent; font-size:14px; }\n  nav button.active { color:#e6edf3; border-color:#3fb950; }\n  main { padding:24px; max-width:1100px; margin:0 auto; }\n  .panel { display:none; }\n  .panel.active { display:block; }\n  .card { background:#161b22; border:1px solid #1f2937; border-radius:10px; padding:20px; margin-bottom:16px; }\n  label { display:block; font-size:12px; color:#8b949e; margin-bottom:4px; margin-top:12px; }\n  input, select { width:100%; padding:8px 10px; background:#0d1117; border:1px solid #30363d; border-radius:6px; color:#e6edf3; font-size:14px; }\n  button.btn { margin-top:16px; padding:9px 16px; background:#238636; border:none; border-radius:6px; color:white; font-size:14px; cursor:pointer; }\n  button.btn.secondary { background:#21262d; border:1px solid #30363d; }\n  button.btn.danger { background:#da3633; }\n  pre { background:#0d1117; border:1px solid #30363d; border-radius:6px; padding:12px; overflow:auto; max-height:340px; font-size:12px; }\n  table { width:100%; border-collapse:collapse; font-size:13px; margin-top:12px; }\n  th, td { text-align:left; padding:8px 10px; border-bottom:1px solid #1f2937; }\n  th { color:#8b949e; font-weight:500; }\n  .bar { height:6px; background:#238636; border-radius:3px; }\n  .barTrack { background:#21262d; border-radius:3px; }\n  .stat { display:inline-block; margin-right:32px; }\n  .stat .n { font-size:22px; font-weight:600; }\n  .stat .l { font-size:12px; color:#8b949e; }\n  .row { display:flex; gap:12px; align-items:flex-end; flex-wrap:wrap; }\n  .row > div { flex:1; min-width:180px; }\n  .muted { color:#8b949e; font-size:12px; }\n  .pill { display:inline-block; padding:2px 8px; border-radius:100px; background:#1f2937; font-size:11px; margin-left:8px; }\n  .status-item { display:inline-flex; align-items:center; gap:6px; margin-right:20px; margin-top:6px; font-size:13px; }\n  .dot { width:9px; height:9px; border-radius:50%; display:inline-block; }\n  .dot.ok { background:#3fb950; }\n  .dot.bad { background:#da3633; }\n</style>\n</head>\n<body>\n\n<header>\n  <h1>🧠 MediaPipe API — Admin</h1>\n  <span class="muted" id="originLabel"></span>\n  <a href="/admin?logout=1" style="color:#8b949e; font-size:12px; margin-left:auto; text-decoration:none;">Đăng xuất</a>\n</header>\n\n<nav>\n  <button class="tabBtn active" data-tab="test">Test kết nối</button>\n  <button class="tabBtn" data-tab="dashboard">Dashboard đo lường & tính tiền</button>\n  <button class="tabBtn" data-tab="keys">Quản lý API key</button>\n</nav>\n\n<main>\n\n  <!-- TEST TAB -->\n  <section class="panel active" id="panel-test">\n    <div class="card">\n      <div class="row" style="align-items:center">\n        <div>\n          <label>Trạng thái hệ thống (không cần API key)</label>\n          <div id="healthGrid" class="muted">Bấm "Kiểm tra" để xem Redis, env var đã cấu hình đúng chưa.</div>\n        </div>\n        <div style="flex:0 0 auto">\n          <button class="btn secondary" id="healthBtn">🩺 Kiểm tra hệ thống</button>\n        </div>\n      </div>\n    </div>\n    <div class="card">\n      <div class="row">\n        <div>\n          <label>Base URL (mặc định = domain hiện tại)</label>\n          <input id="baseUrl" placeholder="https://your-project.vercel.app" />\n        </div>\n        <div>\n          <label>API Key (X-API-Key)</label>\n          <input id="apiKey" placeholder="sk_..." />\n        </div>\n        <div>\n          <label>Endpoint</label>\n          <select id="endpoint">\n            <option value="pose">pose</option>\n            <option value="hand">hand</option>\n            <option value="face">face</option>\n            <option value="gesture">gesture</option>\n          </select>\n        </div>\n      </div>\n      <label>Ảnh test</label>\n      <input id="imageFile" type="file" accept="image/*" />\n      <button class="btn" id="runBtn">▶ Gọi API</button>\n      <button class="btn secondary" id="pingBtn">Kiểm tra kết nối (usage)</button>\n      <p class="muted" id="testStatus"></p>\n    </div>\n    <div class="card">\n      <label>Overlay landmarks</label>\n      <canvas id="overlayCanvas" style="max-width:100%; background:#0d1117; border:1px solid #30363d; border-radius:6px; display:block;"></canvas>\n      <p class="muted" id="overlayHint">Chọn ảnh rồi bấm "Gọi API" để xem overlay.</p>\n    </div>\n    <div class="card">\n      <label>Kết quả (JSON thô)</label>\n      <pre id="result">Chưa có kết quả.</pre>\n    </div>\n  </section>\n\n  <!-- DASHBOARD TAB -->\n  <section class="panel" id="panel-dashboard">\n    <div class="card">\n      <div class="row">\n        <div>\n          <label>Base URL</label>\n          <input id="dashBaseUrl" placeholder="https://your-project.vercel.app" />\n        </div>\n        <div>\n          <label>Admin Secret (X-Admin-Secret)</label>\n          <input id="adminSecret" type="password" placeholder="admin secret" />\n        </div>\n        <div>\n          <label>Tháng (YYYY-MM, để trống = tháng này)</label>\n          <input id="monthInput" placeholder="2026-08" />\n        </div>\n      </div>\n      <button class="btn" id="loadDashBtn">↻ Tải dữ liệu</button>\n      <button class="btn secondary" id="syncStripeBtn">💳 Đồng bộ lên Stripe</button>\n      <p class="muted" id="dashStatus"></p>\n      <p class="muted" id="syncStatus"></p>\n    </div>\n\n    <div class="card" id="statsCard" style="display:none">\n      <div class="stat"><div class="n" id="statKeys">0</div><div class="l">API keys</div></div>\n      <div class="stat"><div class="n" id="statCalls">0</div><div class="l">Tổng lượt gọi</div></div>\n      <div class="stat"><div class="n" id="statCost">$0</div><div class="l">Ước tính tiền phải thu</div></div>\n      <div class="stat"><div class="n" id="statPrice">$0</div><div class="l">Giá / lượt gọi</div></div>\n    </div>\n\n    <div class="card" id="tableCard" style="display:none">\n      <table>\n        <thead><tr><th>API Key</th><th>Nhãn</th><th>Pose</th><th>Hand</th><th>Face</th><th>Gesture</th><th>Tổng</th><th>Ước tính $</th><th>Stripe</th></tr></thead>\n        <tbody id="tableBody"></tbody>\n      </table>\n    </div>\n  </section>\n\n  <!-- KEYS TAB -->\n  <section class="panel" id="panel-keys">\n    <div class="card">\n      <div class="row">\n        <div>\n          <label>Base URL</label>\n          <input id="keysBaseUrl" placeholder="https://your-project.vercel.app" />\n        </div>\n        <div>\n          <label>Admin Secret</label>\n          <input id="keysAdminSecret" type="password" placeholder="admin secret" />\n        </div>\n      </div>\n      <div class="row">\n        <div>\n          <label>API key mới cho khách (đặt tiền tố sk_...)</label>\n          <input id="newKey" placeholder="sk_khach_abc123" />\n        </div>\n        <div>\n          <label>Nhãn / Tên khách (để biết ai là ai khi tính tiền)</label>\n          <input id="newKeyLabel" placeholder="Công ty ABC" />\n        </div>\n        <div>\n          <label>Stripe Customer ID (để tự động thu tiền — tuỳ chọn)</label>\n          <input id="newKeyStripeCustomer" placeholder="cus_..." />\n        </div>\n      </div>\n      <button class="btn" id="addKeyBtn">+ Thêm key</button>\n      <button class="btn secondary" id="loadKeysBtn">↻ Tải danh sách</button>\n      <p class="muted" id="keysStatus"></p>\n    </div>\n    <div class="card">\n      <table>\n        <thead><tr><th>API Key</th><th>Nhãn</th><th>Stripe Customer ID</th><th></th></tr></thead>\n        <tbody id="keysBody"></tbody>\n      </table>\n    </div>\n  </section>\n\n</main>\n\n<script>\nconst $ = (id) => document.getElementById(id);\nconst ADMIN_SECRET_INJECTED = ADMIN_SECRET_JSON_PLACEHOLDER;\ndocument.getElementById(\'originLabel\').textContent = location.origin;\n\n// tabs\ndocument.querySelectorAll(\'.tabBtn\').forEach(btn => {\n  btn.onclick = () => {\n    document.querySelectorAll(\'.tabBtn\').forEach(b => b.classList.remove(\'active\'));\n    document.querySelectorAll(\'.panel\').forEach(p => p.classList.remove(\'active\'));\n    btn.classList.add(\'active\');\n    document.getElementById(\'panel-\' + btn.dataset.tab).classList.add(\'active\');\n  };\n});\n\n// persist small conveniences locally (this is your own deployed page, not a Claude artifact)\nconst persisted = [\'baseUrl\',\'apiKey\',\'dashBaseUrl\',\'adminSecret\',\'keysBaseUrl\',\'keysAdminSecret\'];\npersisted.forEach(id => {\n  const el = $(id);\n  const saved = localStorage.getItem(\'mp_admin_\' + id);\n  if (saved) el.value = saved;\n  el.addEventListener(\'change\', () => localStorage.setItem(\'mp_admin_\' + id, el.value));\n});\n\n// You already proved you know the admin password by logging in, so\n// auto-fill it into the two "Admin Secret" fields instead of asking again.\nif (ADMIN_SECRET_INJECTED) {\n  [\'adminSecret\', \'keysAdminSecret\'].forEach(id => { $(id).value = ADMIN_SECRET_INJECTED; });\n}\n\nfunction fileToBase64(file) {\n  return new Promise((resolve, reject) => {\n    const r = new FileReader();\n    r.onload = () => resolve(r.result.split(\',\')[1]);\n    r.onerror = reject;\n    r.readAsDataURL(file);\n  });\n}\n\nfunction loadImageEl(file) {\n  return new Promise((resolve, reject) => {\n    const img = new Image();\n    img.onload = () => resolve(img);\n    img.onerror = reject;\n    img.src = URL.createObjectURL(file);\n  });\n}\n\n// ---- Overlay drawing (landmarks are normalized 0..1 coords from the API) ----\nconst POSE_CONNECTIONS = [\n  [11,12],[11,13],[13,15],[15,17],[15,19],[15,21],[17,19],\n  [12,14],[14,16],[16,18],[16,20],[16,22],[18,20],\n  [11,23],[12,24],[23,24],[23,25],[24,26],[25,27],[26,28],\n  [27,29],[28,30],[29,31],[30,32],[27,31],[28,32],\n  [0,1],[1,2],[2,3],[3,7],[0,4],[4,5],[5,6],[6,8],[9,10],\n];\nconst HAND_CONNECTIONS = [\n  [0,1],[1,2],[2,3],[3,4],\n  [0,5],[5,6],[6,7],[7,8],\n  [5,9],[9,10],[10,11],[11,12],\n  [9,13],[13,14],[14,15],[15,16],\n  [13,17],[17,18],[18,19],[19,20],[0,17],\n];\n\nlet currentImageEl = null; // last loaded <img> for the selected file\n\nfunction drawBaseImage() {\n  const canvas = $(\'overlayCanvas\');\n  if (!currentImageEl) return null;\n  const maxW = 560;\n  const scale = Math.min(1, maxW / currentImageEl.naturalWidth);\n  canvas.width = currentImageEl.naturalWidth * scale;\n  canvas.height = currentImageEl.naturalHeight * scale;\n  const ctx = canvas.getContext(\'2d\');\n  ctx.drawImage(currentImageEl, 0, 0, canvas.width, canvas.height);\n  return ctx;\n}\n\nfunction drawPoints(ctx, points, color, radius) {\n  ctx.fillStyle = color;\n  points.forEach(p => {\n    ctx.beginPath();\n    ctx.arc(p.x * ctx.canvas.width, p.y * ctx.canvas.height, radius, 0, Math.PI * 2);\n    ctx.fill();\n  });\n}\n\nfunction drawConnections(ctx, points, connections, color) {\n  ctx.strokeStyle = color;\n  ctx.lineWidth = 2;\n  connections.forEach(([a, b]) => {\n    if (!points[a] || !points[b]) return;\n    ctx.beginPath();\n    ctx.moveTo(points[a].x * ctx.canvas.width, points[a].y * ctx.canvas.height);\n    ctx.lineTo(points[b].x * ctx.canvas.width, points[b].y * ctx.canvas.height);\n    ctx.stroke();\n  });\n}\n\nfunction renderOverlay(endpoint, data) {\n  const ctx = drawBaseImage();\n  if (!ctx) return;\n  const frame = data.results && data.results[0]; // preview only overlays the first frame\n  if (!frame) { $(\'overlayHint\').textContent = \'Không có kết quả để vẽ overlay.\'; return; }\n\n  if (endpoint === \'pose\') {\n    const poses = frame.poses || [];\n    poses.forEach(pts => {\n      drawConnections(ctx, pts, POSE_CONNECTIONS, \'#3fb950\');\n      drawPoints(ctx, pts, \'#f0883e\', 3);\n    });\n    $(\'overlayHint\').textContent = poses.length ? `${poses.length} pose(s) phát hiện được.` : \'Không phát hiện pose nào.\';\n\n  } else if (endpoint === \'hand\') {\n    const hands = frame.hands || [];\n    hands.forEach(h => {\n      drawConnections(ctx, h.landmarks, HAND_CONNECTIONS, \'#58a6ff\');\n      drawPoints(ctx, h.landmarks, \'#f0883e\', 3);\n    });\n    $(\'overlayHint\').textContent = hands.length\n      ? hands.map(h => h.handedness).join(\', \') + \' — \' + hands.length + \' tay phát hiện được.\'\n      : \'Không phát hiện tay nào.\';\n\n  } else if (endpoint === \'face\') {\n    const faces = frame.faces || [];\n    faces.forEach(f => drawPoints(ctx, f.landmarks, \'#d2a8ff\', 1.2));\n    $(\'overlayHint\').textContent = faces.length ? `${faces.length} khuôn mặt phát hiện được.` : \'Không phát hiện khuôn mặt nào.\';\n\n  } else if (endpoint === \'gesture\') {\n    const hands = frame.hands || [];\n    ctx.font = \'bold 16px sans-serif\';\n    hands.forEach((h, i) => {\n      const label = `${h.handedness || \'?\'}: ${h.gesture || \'Không rõ\'} (${h.score ? (h.score * 100).toFixed(0) + \'%\' : \'—\'})`;\n      ctx.fillStyle = \'#0d1117\';\n      ctx.fillRect(8, 8 + i * 26, ctx.measureText(label).width + 12, 22);\n      ctx.fillStyle = \'#3fb950\';\n      ctx.fillText(label, 14, 24 + i * 26);\n    });\n    $(\'overlayHint\').textContent = hands.length\n      ? \'Endpoint gesture không trả toạ độ điểm, chỉ nhãn cử chỉ — hiển thị dạng chữ.\'\n      : \'Không phát hiện tay nào.\';\n  }\n}\n\n$(\'imageFile\').addEventListener(\'change\', async () => {\n  const file = $(\'imageFile\').files[0];\n  if (!file) return;\n  currentImageEl = await loadImageEl(file);\n  drawBaseImage();\n  $(\'overlayHint\').textContent = \'Đã tải ảnh xem trước. Bấm "Gọi API" để vẽ overlay.\';\n});\n\n// ---- Health check (no API key needed) ----\n$(\'healthBtn\').onclick = async () => {\n  const base = $(\'baseUrl\').value.trim() || location.origin;\n  $(\'healthGrid\').textContent = \'Đang kiểm tra...\';\n  try {\n    const res = await fetch(base + \'/api/health\');\n    const d = await res.json();\n    const item = (ok, label) => `<span class="status-item"><span class="dot ${ok ? \'ok\' : \'bad\'}"></span>${label}</span>`;\n    $(\'healthGrid\').innerHTML =\n      item(d.redis_connected, \'Redis kết nối được\') +\n      item(d.upstash_env_vars_set, \'Env var Upstash đã set\') +\n      item(d.admin_secret_set, \'ADMIN_SECRET đã set\') +\n      item(d.ready, d.ready ? \'Sẵn sàng dùng\' : \'Chưa sẵn sàng — kiểm tra lại env var\') +\n      `<span class="status-item muted">Giá/lượt: $${d.price_per_call_usd} · Rate limit: ${d.rate_limit_per_minute || \'không giới hạn\'}</span>`;\n  } catch (e) {\n    $(\'healthGrid\').textContent = \'✗ Không gọi được /api/health: \' + e.message;\n  }\n};\n\n// ---- Test tab ----\n$(\'runBtn\').onclick = async () => {\n  const base = $(\'baseUrl\').value.trim() || location.origin;\n  const key = $(\'apiKey\').value.trim();\n  const endpoint = $(\'endpoint\').value;\n  const file = $(\'imageFile\').files[0];\n  if (!key) return $(\'testStatus\').textContent = \'Nhập API key trước.\';\n  if (!file) return $(\'testStatus\').textContent = \'Chọn ảnh test trước.\';\n  $(\'testStatus\').textContent = \'Đang gọi \' + endpoint + \'...\';\n  $(\'result\').textContent = \'\';\n  try {\n    const b64 = await fileToBase64(file);\n    const t0 = performance.now();\n    const res = await fetch(base + \'/api/\' + endpoint, {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\', \'X-API-Key\': key },\n      body: JSON.stringify({ image: b64 }),\n    });\n    const ms = Math.round(performance.now() - t0);\n    const data = await res.json();\n    $(\'testStatus\').textContent = res.ok\n      ? `✓ Thành công (${res.status}) — ${ms}ms`\n      : `✗ Lỗi (${res.status}) — ${ms}ms`;\n    $(\'result\').textContent = JSON.stringify(data, null, 2);\n    if (res.ok) renderOverlay(endpoint, data);\n  } catch (e) {\n    $(\'testStatus\').textContent = \'✗ Lỗi kết nối: \' + e.message;\n  }\n};\n\n$(\'pingBtn\').onclick = async () => {\n  const base = $(\'baseUrl\').value.trim() || location.origin;\n  const key = $(\'apiKey\').value.trim();\n  if (!key) return $(\'testStatus\').textContent = \'Nhập API key trước.\';\n  $(\'testStatus\').textContent = \'Đang kiểm tra...\';\n  try {\n    const res = await fetch(base + \'/api/usage\', { headers: { \'X-API-Key\': key } });\n    const data = await res.json();\n    $(\'testStatus\').textContent = res.ok ? \'✓ Kết nối OK, key hợp lệ\' : \'✗ Key không hợp lệ hoặc lỗi server\';\n    $(\'result\').textContent = JSON.stringify(data, null, 2);\n  } catch (e) {\n    $(\'testStatus\').textContent = \'✗ Lỗi kết nối: \' + e.message;\n  }\n};\n\n// ---- Dashboard tab ----\n$(\'loadDashBtn\').onclick = async () => {\n  const base = $(\'dashBaseUrl\').value.trim() || location.origin;\n  const secret = $(\'adminSecret\').value.trim();\n  const month = $(\'monthInput\').value.trim();\n  if (!secret) return $(\'dashStatus\').textContent = \'Nhập admin secret trước.\';\n  $(\'dashStatus\').textContent = \'Đang tải...\';\n  try {\n    const url = base + \'/api/admin-overview\' + (month ? \'?month=\' + encodeURIComponent(month) : \'\');\n    const res = await fetch(url, { headers: { \'X-Admin-Secret\': secret } });\n    const data = await res.json();\n    if (!res.ok) { $(\'dashStatus\').textContent = \'✗ \' + (data.error || \'Lỗi\'); return; }\n    $(\'dashStatus\').textContent = \'Đã tải — tháng \' + data.month;\n    $(\'statsCard\').style.display = \'block\';\n    $(\'tableCard\').style.display = \'block\';\n    $(\'statKeys\').textContent = data.total_keys;\n    $(\'statCalls\').textContent = data.total_requests;\n    $(\'statCost\').textContent = \'$\' + data.total_estimated_cost_usd;\n    $(\'statPrice\').textContent = \'$\' + data.price_per_call_usd;\n\n    const maxReq = Math.max(1, ...data.keys.map(k => k.total_requests));\n    $(\'tableBody\').innerHTML = data.keys.map(k => `\n      <tr>\n        <td>${maskKey(k.api_key)}<br/>\n          <div class="barTrack" style="width:120px"><div class="bar" style="width:${(k.total_requests / maxReq * 100).toFixed(0)}%"></div></div>\n        </td>\n        <td>${k.label || \'<span class="muted">—</span>\'}</td>\n        <td>${k.by_endpoint.pose || 0}</td>\n        <td>${k.by_endpoint.hand || 0}</td>\n        <td>${k.by_endpoint.face || 0}</td>\n        <td>${k.by_endpoint.gesture || 0}</td>\n        <td><b>${k.total_requests}</b></td>\n        <td>$${k.estimated_cost_usd}</td>\n        <td>${k.stripe_customer_id ? `${k.stripe_customer_id}<br/><span class="muted">đã báo: ${k.stripe_synced_count}</span>` : \'<span class="muted">chưa gắn</span>\'}</td>\n      </tr>\n    `).join(\'\') || \'<tr><td colspan="9" class="muted">Chưa có key nào / chưa có usage.</td></tr>\';\n  } catch (e) {\n    $(\'dashStatus\').textContent = \'✗ Lỗi kết nối: \' + e.message;\n  }\n};\n\nfunction maskKey(k) {\n  if (k.length <= 8) return k;\n  return k.slice(0, 6) + \'…\' + k.slice(-4);\n}\n\n$(\'syncStripeBtn\').onclick = async () => {\n  const base = $(\'dashBaseUrl\').value.trim() || location.origin;\n  const secret = $(\'adminSecret\').value.trim();\n  if (!secret) return $(\'syncStatus\').textContent = \'Nhập admin secret trước.\';\n  $(\'syncStatus\').textContent = \'Đang đồng bộ lên Stripe...\';\n  try {\n    const res = await fetch(base + \'/api/admin-stripe-sync\', {\n      method: \'POST\',\n      headers: { \'X-Admin-Secret\': secret },\n    });\n    const data = await res.json();\n    if (!res.ok) { $(\'syncStatus\').textContent = \'✗ \' + (data.error || \'Lỗi\'); return; }\n    const okCount = data.results.filter(r => r.status === \'ok\').length;\n    const errCount = data.results.filter(r => r.status === \'error\').length;\n    const totalReported = data.results.reduce((s, r) => s + (r.reported || 0), 0);\n    $(\'syncStatus\').textContent = `✓ Đã báo ${totalReported} lượt gọi lên Stripe cho ${okCount} key` +\n      (errCount ? ` — ${errCount} key lỗi (xem console)` : \'\') +\n      (data.keys_with_stripe_customer === 0 ? \' — chưa có key nào gắn Stripe Customer ID\' : \'\');\n    if (errCount) console.log(\'Stripe sync errors:\', data.results.filter(r => r.status === \'error\'));\n    $(\'loadDashBtn\').click();\n  } catch (e) {\n    $(\'syncStatus\').textContent = \'✗ Lỗi kết nối: \' + e.message;\n  }\n};\n\n// ---- Keys tab ----\n$(\'loadKeysBtn\').onclick = async () => {\n  const base = $(\'keysBaseUrl\').value.trim() || location.origin;\n  const secret = $(\'keysAdminSecret\').value.trim();\n  if (!secret) return $(\'keysStatus\').textContent = \'Nhập admin secret trước.\';\n  $(\'keysStatus\').textContent = \'Đang tải...\';\n  try {\n    const res = await fetch(base + \'/api/admin-keys\', { headers: { \'X-Admin-Secret\': secret } });\n    const data = await res.json();\n    if (!res.ok) { $(\'keysStatus\').textContent = \'✗ \' + (data.error || \'Lỗi\'); return; }\n    $(\'keysStatus\').textContent = data.keys.length + \' key.\';\n    $(\'keysBody\').innerHTML = data.keys.map(k => `\n      <tr><td>${k.api_key}</td><td>${k.label || \'<span class="muted">—</span>\'}</td><td>${k.stripe_customer_id || \'<span class="muted">—</span>\'}</td><td><button class="btn danger" data-key="${k.api_key}">Xoá</button></td></tr>\n    `).join(\'\') || \'<tr><td colspan="4" class="muted">Chưa có key nào.</td></tr>\';\n    $(\'keysBody\').querySelectorAll(\'button[data-key]\').forEach(btn => {\n      btn.onclick = async () => {\n        await fetch(base + \'/api/admin-keys\', {\n          method: \'DELETE\',\n          headers: { \'Content-Type\': \'application/json\', \'X-Admin-Secret\': secret },\n          body: JSON.stringify({ api_key: btn.dataset.key }),\n        });\n        $(\'loadKeysBtn\').click();\n      };\n    });\n  } catch (e) {\n    $(\'keysStatus\').textContent = \'✗ Lỗi kết nối: \' + e.message;\n  }\n};\n\n$(\'addKeyBtn\').onclick = async () => {\n  const base = $(\'keysBaseUrl\').value.trim() || location.origin;\n  const secret = $(\'keysAdminSecret\').value.trim();\n  const newKey = $(\'newKey\').value.trim();\n  const label = $(\'newKeyLabel\').value.trim();\n  const stripeCustomerId = $(\'newKeyStripeCustomer\').value.trim();\n  if (!secret) return $(\'keysStatus\').textContent = \'Nhập admin secret trước.\';\n  if (!newKey) return $(\'keysStatus\').textContent = \'Nhập giá trị key mới trước.\';\n  $(\'keysStatus\').textContent = \'Đang thêm...\';\n  try {\n    const res = await fetch(base + \'/api/admin-keys\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\', \'X-Admin-Secret\': secret },\n      body: JSON.stringify({ api_key: newKey, label, stripe_customer_id: stripeCustomerId }),\n    });\n    const data = await res.json();\n    $(\'keysStatus\').textContent = res.ok ? \'✓ Đã thêm \' + data.added : \'✗ \' + (data.error || \'Lỗi\');\n    $(\'newKey\').value = \'\';\n    $(\'newKeyLabel\').value = \'\';\n    $(\'newKeyStripeCustomer\').value = \'\';\n    $(\'loadKeysBtn\').click();\n  } catch (e) {\n    $(\'keysStatus\').textContent = \'✗ Lỗi kết nối: \' + e.message;\n  }\n};\n</script>\n</body>\n</html>\n'

def render_dashboard(admin_secret):
    import json
    return DASHBOARD_HTML_TEMPLATE.replace(
        "ADMIN_SECRET_JSON_PLACEHOLDER", json.dumps(admin_secret)
    )
